'use client';

import React, { FormEvent, ReactNode, useState } from 'react';
import { validateResident } from '@/lib/residentValidation';
import type { ResidentErrors } from '@/lib/residentValidation';

// Name + email sign-up form (the former /auth/signup form, now reusable).
// It posts to `endpoint` and hands the parsed JSON response to `onSuccess`.
// The password is generated by the server, so there are no password fields.
export type SignupResponse = {
  user: { name: string; email: string };
  tempPassword: string;
};

type SignupFormProps = {
  endpoint: string;
  submitLabel?: string;
  onSuccess: (data: SignupResponse) => void;
  footer?: ReactNode;
};

const inputClass =
  'border border-gray-300 rounded px-3 py-2 text-black focus:outline-none focus:border-blue-500';

const SignupForm = ({ endpoint, submitLabel = 'Create Account', onSuccess, footer }: SignupFormProps) => {
  const [name, setName] = useState('');
  const [email, setEmail] = useState('');
  const [errors, setErrors] = useState<ResidentErrors>({});
  const [error, setError] = useState('');
  const [isLoading, setIsLoading] = useState(false);

  const handleSubmit = async (e: FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    setError('');

    const found = validateResident({ name, email });
    setErrors(found);
    if (Object.keys(found).length > 0) return;

    setIsLoading(true);
    try {
      const response = await fetch(endpoint, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ name: name.trim(), email: email.trim() }),
      });

      if (response.status === 409) {
        setErrors({ email: 'An account with this email already exists.' });
        return;
      }
      if (!response.ok) {
        throw new Error();
      }

      onSuccess((await response.json()) as SignupResponse);
    } catch {
      setError("We couldn't create the account. Try again in a moment.");
    } finally {
      setIsLoading(false);
    }
  };

  const clear = () => {
    setName('');
    setEmail('');
    setErrors({});
    setError('');
  };

  return (
    <form className="flex flex-col gap-y-4" onSubmit={handleSubmit} noValidate>
      <div className="flex flex-col gap-y-1">
        <input
          type="text"
          placeholder="Full Name"
          aria-label="Full name"
          value={name}
          onChange={(e) => setName(e.target.value)}
          autoComplete="off"
          aria-invalid={!!errors.name}
          className={inputClass}
        />
        {errors.name && <p className="text-sm text-red-700">{errors.name}</p>}
      </div>
      <div className="flex flex-col gap-y-1">
        <input
          type="email"
          placeholder="Email"
          aria-label="Email"
          value={email}
          onChange={(e) => setEmail(e.target.value)}
          autoComplete="off"
          aria-invalid={!!errors.email}
          className={inputClass}
        />
        {errors.email && <p className="text-sm text-red-700">{errors.email}</p>}
      </div>
      {error && <p role="alert" className="text-red-500">{error}</p>}
      <div className="flex gap-3">
        <button
          type="button"
          onClick={clear}
          disabled={isLoading}
          className="border border-gray-300 text-black py-2 px-4 rounded hover:bg-gray-50 disabled:opacity-50"
        >
          Clear form
        </button>
        <button
          type="submit"
          disabled={isLoading}
          className="flex-grow bg-[#29abe2] text-white py-2 rounded hover:bg-[#64bee3] disabled:bg-[#64bee3]"
        >
          {isLoading ? 'Creating Account...' : submitLabel}
        </button>
      </div>
      {footer}
    </form>
  );
};

export default SignupForm;
